class QueueError extends Error {
  name = "QueueError";
}

class FullError extends QueueError {
  constructor(size) {
    super(`queue holds ${size}`);
    this.size = size;
  }
}

const full = new FullError(3);
const outer = new QueueError("push failed", { cause: full });

console.log(full.name, full.message);
console.log(outer.cause.size);
console.log(outer.cause instanceof QueueError);
console.log(Object.keys(full).join(","));
